final Map<String, Path> _cache = {};

Path _pathOf(String n) => _cache[n] ??= parseSvgPathData(kWebIcons[n] ?? kWebIcons['info']!);

/// أيقونة بنفس مسار الويب (24×24). تأخذ لون IconTheme إن لم يُحدَّد لون.
class WIcon extends StatelessWidget {
  final String name;
  final double size;
  final Color? color;
  const WIcon(this.name, {super.key, this.size = 22, this.color});
  @override
  Widget build(BuildContext context) {
    final c = color ?? IconTheme.of(context).color ?? Theme.of(context).colorScheme.onSurface;
    return SizedBox(width: size, height: size, child: CustomPaint(painter: _WIconPainter(_pathOf(name), c)));
  }
}

class _WIconPainter extends CustomPainter {
  final Path path;
  final Color color;
  _WIconPainter(this.path, this.color);
  @override
  void paint(Canvas canvas, Size s) {
    canvas.save();
    canvas.scale(s.width / 24, s.height / 24);
    canvas.drawPath(path, Paint()..color = color..style = PaintingStyle.fill..isAntiAlias = true);
    canvas.restore();
  }

  @override
  bool shouldRepaint(_WIconPainter o) => o.path != path || o.color != color;
}
